const OWNER_ID = ''; // Укажите разрешённый Telegram ID в приватной копии.
const m = $input.first().json.message;
if (!/^[1-9]\d+$/.test(OWNER_ID) || m?.chat?.type !== 'private' || String(m.from?.id) !== OWNER_ID || String(m.chat.id) !== OWNER_ID || m.from.is_bot !== false) return [];
if (typeof m.text !== 'string' || !m.text.trim() || m.text.trimStart().startsWith('/') || !Number.isSafeInteger(m.date) || m.date <= 0 || m.date > 4102444800 || !Number.isSafeInteger(m.message_id) || m.message_id <= 0) return [];
return [{json:{message:m}}];

// Часовой пояс журнала: по умолчанию UTC. При необходимости задайте своё смещение в минутах.
const REPORT_UTC_OFFSET_MINUTES = 0;
function parse(m) {
  const original = m.text;
  const text = original.normalize('NFKC').replace(/\s+/g, ' ').trim();
  const received = new Date(m.date * 1000 + REPORT_UTC_OFFSET_MINUTES * 60000).toISOString().slice(0,10);
  const result = {id:`tg:${m.chat.id}:${m.message_id}`, date:received, month:received.slice(0,7), kind:'На проверке', model:'', amount:'', link:'', original, note:'', reply:m.reply_to_message?.message_id || null};
  const review = reason => ({...result, note:reason});
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const dateRx = new RegExp('^(\\d{1,2}) ('+months.join('|')+')(?: (\\d{4})(?: г\\.?)?)?\\s*[,;]?\\s+', 'iu');
  const d = text.match(dateRx);
  if (!d) return review('Нужна дата в начале сообщения: например, 8 февраля.');
  const month = months.indexOf(d[2].toLowerCase()) + 1;
  const dateFor = y => `${y}-${String(month).padStart(2,'0')}-${d[1].padStart(2,'0')}`;
  let year = d[3] ? Number(d[3]) : Number(received.slice(0,4));
  if (!d[3] && dateFor(year) > received) return review('Дата без года позже даты сообщения. Укажите год.');
  const date = dateFor(year);
  const stamp = new Date(date + 'T00:00:00Z');
  if (year < 1900 || !Number.isFinite(stamp.getTime()) || stamp.toISOString().slice(0,10) !== date || date > received) return review('Неверная или будущая дата события.');
  result.date = date;
  result.month = date.slice(0,7);
  const rest = text.slice(d[0].length);
  const negative = /(?:не\s+продал[аи]?|(?:отмен[а-яё]+|сорвал[а-яё]*|перен[её]с[а-яё]*|возврат[а-яё]*)|не\s+(?:совершен[а-яё]*|состоял[а-яё]*|заверш[а-яё]*))/iu;
  const sale = 'продал(?:а|и)?';
  const request = '(?:договорил(?:ся|ась|ись) по заявке о продаже|(?:поступила|получил(?:а|и)?) заявка на продажу)';
  const classify = new RegExp('^(' + sale + '|' + request + ') (?:автомобил[ья] )?(.+?) за (\\d{1,3}(?: \\d{3})+|\\d+)([,.]\\d{1,2})? *(млн\\.?|миллион(?:а|ов)?|тыс\\.?|тысяч(?:а|и)?)? *(руб(?:лей|ля|ль)?\\.?|₽)(.*)$', 'iu');
  const match = rest.match(classify);
  if (!match) return review('Не удалось однозначно разобрать тип, автомобиль и сумму в рублях.');
  const [,verb,model,whole,fraction,unit,currency,tail] = match;
  const isSale = new RegExp('^'+sale+'$', 'iu').test(verb);
  const cleanTail = tail.trim().replace(/^[.!]\s*/, '').replace(/[.!]$/, '').trim();
  if (cleanTail && !( !isSale && /^сделка (?:еще |ещё |пока )?не (?:совершена|состоялась|завершена)$/iu.test(cleanTail))) return review('Есть дополнительные условия или неясный статус.');
  if (negative.test(rest.slice(0,rest.length - tail.length)) || !/^[\p{L}\p{N}][\p{L}\p{N} .+–-]{1,79}$/u.test(model)) return review('Неоднозначный статус или название автомобиля.');
  const value = Number(whole.replace(/ /g,'') + (fraction || '').replace(',','.'));
  const mult = /^м/iu.test(unit || '') ? 1000000 : /^т/iu.test(unit || '') ? 1000 : 1;
  const amount = Math.round(value * mult * 100) / 100;
  if (!Number.isFinite(amount) || amount <= 0 || amount > 1e10) return review('Проверьте сумму.');
  return {...result,kind:isSale?'Продажа':'Заявка',model:model.trim(),amount};
}

return $input.all().map(({json})=>({json:parse(json.message)}));

const values = $input.first().json.values;
if (!Array.isArray(values) || values[0]?.[0] !== 'ID сообщения' || values[0]?.[6] !== 'ID заявки (если связан)') throw new Error('Проверьте шапку листа SalesLog.');
const p = $('Разобрать сообщение').first().json;
const rows = values.slice(1);
if (rows.some(r => r[0] === p.id)) return [];
if (p.reply && p.kind === 'Продажа') {
  const parent = p.id.replace(/:\d+$/, ':' + p.reply);
  const found = rows.filter(r => r[0] === parent && r[3] === 'Заявка');
  const normalize = s => String(s).normalize('NFKC').replace(/\s+/g,' ').trim().toLowerCase();
  if (found.length === 1 && normalize(found[0][4]) === normalize(p.model) && found[0][1] <= p.date && !rows.some(r => r[3] === 'Продажа' && r[6] === parent)) p.link = parent;
  else { p.kind = 'На проверке'; p.note = 'Ответ на сообщение: связь с заявкой не подтверждена. Проверьте вручную.'; }
}
return [{json:{values:[[p.id,p.date,p.month,p.kind,p.model,p.amount,p.link,p.original,p.note]]}}];

