const samples = ["3 февраля поступила заявка на продажу автомобиля Демо Альфа за 120 тыс. руб.", "8 февраля продал Демо Бета за 230 тыс. руб."].map((text, i) => ({text, date:Date.UTC(2030, 1, 15) / 1000, chat:{id:1}, message_id:i+1}));
const rows = samples.map(parse);
if (rows[0].kind !== 'Заявка' || rows[0].amount !== 120000 || rows[1].kind !== 'Продажа' || rows[1].amount !== 230000 || rows.some((r,i)=>r.date !== ['2030-02-03','2030-02-08'][i])) throw new Error('Не совпали контрольные результаты.');
return rows.map(json=>({json}));
